"use strict";{let o=`
<form id="passwordreset">
<webui-input-text theme="primary" name="password" type="password" label="Password"></webui-input-text>
<webui-input-text theme="primary" name="confirmPassword" type="password" label="Confirm Password"></webui-input-text>
<webui-flex justify="end" align="center" class="pa-3">
    <webui-button type="submit" theme="primary" start-icon="confirm">Reset Password</webui-button>
</webui-flex>
<webui-alert severity="danger"></webui-alert>
</form>
`;webui.define("app-passwordreset",{content:!0,watchVisibility:!1,isInput:!1,preload:"",flags:[],attr:["height","max-height"],attrChanged(r,a){const e=this;switch(r){case"height":e.style.height=webui.pxIfNumber(a);break;case"maxHeight":e.style.maxHeight=webui.pxIfNumber(a);break}},connected(){this.setupComponent()},setupComponent(){const r=this;r.innerHTML=o;let a=r.querySelector("#passwordreset"),e=r.querySelector("webui-alert");a.addEventListener("submit",n=>{n.stopPropagation(),n.preventDefault(),e.setValue();const u=new FormData(a),t=Object.fromEntries(u);t.token=location.pathname.split("/").pop();try{webui.fromBase64(t.token)}catch{e.setValue("Invalid token");return}if(!t.token){e.setValue("Missing expected token");return}if(!t.password){e.setValue("Password is required");return}if(!t.confirmPassword){e.setValue("Please confirm your password");return}if(t.password!==t.confirmPassword){e.setValue("Password and Confirm Password do not match");return}let i;return webui.fetchApi("user/confirm/passwordreset",t).then(s=>(i=s,i.text())).then(s=>{i.status===200?(webui.alert(s||"Password was successfully reset. You may now sign-in with your email and password.","success"),webui.navigateTo("/signin")):e.setValue(s||"Failed to finish update password. Please wait a moment and try again.")}).catch(s=>{e.setValue(`Error: ${s}`)}),!1})}})}
